import{_ as r,C as a,o as s,c as l,j as t,a as o,E as i,ag as c}from"./chunks/framework.HG0H2VLS.js";const q=JSON.parse('{"title":"MediaPicker","description":"","frontmatter":{},"headers":[],"relativePath":"cc-components/media-picker.md","filePath":"cc-components/media-picker.md"}'),h={name:"cc-components/media-picker.md"},m={id:"mediapicker",tabindex:"-1"};function p(u,e,b,g,f,k){const d=a("Badge"),n=a("ComponentDemo");return s(),l("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-mediapicker",tabindex:"-1"},[o("title: MediaPicker "),t("a",{class:"header-anchor",href:"#title-mediapicker","aria-label":'Permalink to "title: MediaPicker"'},"​")],-1)),t("h1",m,[e[0]||(e[0]=o("MediaPicker ",-1)),i(d,{type:"info",text:"Design System"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#mediapicker","aria-label":'Permalink to "MediaPicker <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"Edit-mode image field: 56px thumbnail (Empty / Filled) + Edit + delete")],-1)),i(n,{src:"/demos/src/cc/components/MediaPicker/MediaPicker.html"}),e[6]||(e[6]=c('<h2 id="token-gaps-decisions" tabindex="-1">Token Gaps &amp; Decisions <a class="header-anchor" href="#token-gaps-decisions" aria-label="Permalink to &quot;Token Gaps &amp; Decisions&quot;">​</a></h2><p>Figma image icon is bound to <code>--ai-border-primary</code>; code uses <code>--ai-icon-secondary</code> (same #667f89 in CC, correct semantic). Edit/delete wiring is backend.</p><h2 id="edit-button-icon-only-designer-2026-09-29" tabindex="-1">Edit button: icon only (designer, 2026-09-29) <a class="header-anchor" href="#edit-button-icon-only-designer-2026-09-29" aria-label="Permalink to &quot;Edit button: icon only (designer, 2026-09-29)&quot;">​</a></h2><p>The Edit action is now <code>btn btn--secondary btn--sm btn--icon</code> with only the pencil and <code>aria-label=&quot;Edit &lt;field&gt;&quot;</code>. The text label is dropped. It opens the Selector Type=Media (<code>data-selector-open=&quot;modal-media&quot;</code>) on the record screens. <strong>Figma still shows &quot;Edit&quot; with text, so flag it for Figma.</strong></p><h2 id="thumbnail-opens-the-selector-designer-2026-09-29" tabindex="-1">Thumbnail opens the selector (designer, 2026-09-29) <a class="header-anchor" href="#thumbnail-opens-the-selector-designer-2026-09-29" aria-label="Permalink to &quot;Thumbnail opens the selector (designer, 2026-09-29)&quot;">​</a></h2><p><code>.media-picker__thumb</code> is now a <code>&lt;button&gt;</code> (<code>aria-label=&quot;Choose &lt;field&gt;&quot;</code>). Clicking the image or the empty placeholder opens the Selector Type=Media, the same as Edit. On hover it takes a <code>--ai-border-brand</code> border, and focus shows the standard ring. The file kind (audio) keeps a plain span thumb.</p><h2 id="empty-vs-filled-designer-2026-09-29" tabindex="-1">Empty vs filled (designer, 2026-09-29) <a class="header-anchor" href="#empty-vs-filled-designer-2026-09-29" aria-label="Permalink to &quot;Empty vs filled (designer, 2026-09-29)&quot;">​</a></h2><ul><li><strong>Empty slot</strong> (<code>media-picker--empty</code>): the placeholder plus <strong>Choose file</strong> (secondary sm, upload icon).</li><li><strong>Filled slot</strong>: the image plus the pencil (change) and trash (remove).</li></ul><p>Both action sets are in the markup and the modifier picks one. MediaPicker.js does the trash: it empties the slot and moves focus to Choose file. Choosing in the Selector fills the slot through <code>window.mediaPicker.fill</code>.</p><p>On the record screens, FieldRow hides the image options while the slot is empty. Handover: <code>record-media-remove</code>. <strong>Flag for Figma:</strong> the empty state with Choose file is not drawn yet.</p><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Variant</th><th>Notes</th></tr></thead><tbody><tr><td><code>3875:3331</code></td><td>State=Empty</td><td>image icon in the thumb</td></tr><tr><td><code>3875:3331</code></td><td>State=Filled</td><td>image in the thumb</td></tr></tbody></table><h2 id="css-classes" tabindex="-1">CSS Classes <a class="header-anchor" href="#css-classes" aria-label="Permalink to &quot;CSS Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td>Root</td><td><code>.media-picker</code></td></tr><tr><td>Thumbnail</td><td><code>.media-picker__thumb (icon or img)</code></td></tr><tr><td>Actions</td><td><code>.media-picker__actions → btn btn--secondary btn--sm &quot;Edit&quot; + btn--sm btn--icon trash</code></td></tr></tbody></table><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>thumb size</td><td>--ai-spacing-10 (56)</td></tr><tr><td>thumb bg / border / radius</td><td>--ai-surface-minimal / --ai-border-secondary / --ai-radius-md (designer amend 2026-09-29, was -sm — flag for Figma)</td></tr><tr><td>image icon</td><td>--ai-icon-size-md, --ai-icon-secondary</td></tr><tr><td>gap thumb→actions / between buttons</td><td>--ai-spacing-4 / --ai-spacing-2</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Built 2026-09-28 from the View &amp; Edit kit (section <code>3861:1902</code>, CC Light mode). The kit was componentised from a code-capture draft that re-tokenise had bound to random / borrowed tokens; the designer ruled &quot;your recommendations are the way to go&quot;, so bindings were normalised to the right semantic tokens in Figma first and this code follows the kit, not the draft.</li><li>Markup comes from <code>src/cc/templates/RecordScreen/record_markup.py</code> — the demo and the templates are generated from the same function, so they cannot drift.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=3875-3331" target="_blank" rel="noreferrer">Open in Figma</a></p>',20))])}const P=r(h,[["render",p]]);export{q as __pageData,P as default};
